<script>
// ── MOBILE NAV ──────────────────────────────────────────
const mobileToggle = document.getElementById('mobileToggle');
const navLinks = document.getElementById('navLinks');
mobileToggle.addEventListener('click', () => {
  navLinks.classList.toggle('open');
});

// ── STAT COUNTER ────────────────────────────────────────
function formatNumber(n) {
  return n.toLocaleString('en-US');
}

function animateCounter(el, target, duration = 1800) {
  let start = 0;
  const step = timestamp => {
    if (!start) start = timestamp;
    const progress = Math.min((timestamp - start) / duration, 1);
    // ease-out cubic
    const eased = 1 - Math.pow(1 - progress, 3);
    const current = Math.round(eased * target);
    el.textContent = formatNumber(current);
    if (progress < 1) requestAnimationFrame(step);
  };
  requestAnimationFrame(step);
}

const statsSection = document.getElementById('statsSection');
let statsAnimated = false;

const statsObserver = new IntersectionObserver(entries => {
  entries.forEach(entry => {
    if (entry.isIntersecting && !statsAnimated) {
      statsAnimated = true;
      const counters = statsSection.querySelectorAll('.stat-number[data-target]');
      counters.forEach((el, i) => {
        const target = parseInt(el.dataset.target, 10);
        setTimeout(() => animateCounter(el, target), i * 180);
      });
    }
  });
}, { threshold: 0.3 });

statsObserver.observe(statsSection);

// ── SEARCH TABS ─────────────────────────────────────────
document.querySelectorAll('.tab-btn').forEach(btn => {
  btn.addEventListener('click', () => {
    document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
    document.querySelectorAll('.tab-content').forEach(c => c.classList.remove('active'));
    btn.classList.add('active');
    const tabId = 'tab-' + btn.dataset.tab;
    const target = document.getElementById(tabId);
    if (target) {
      target.classList.add('active');
      target.style.opacity = '0';
      target.style.transform = 'translateY(8px)';
      requestAnimationFrame(() => {
        target.style.transition = 'opacity 0.22s ease, transform 0.22s ease';
        target.style.opacity = '1';
        target.style.transform = 'translateY(0)';
      });
    }
  });
});

// ── FILTER PILLS ────────────────────────────────────────
document.querySelectorAll('.pill').forEach(pill => {
  pill.addEventListener('click', () => {
    document.querySelectorAll('.pill').forEach(p => p.classList.remove('active'));
    pill.classList.add('active');
    // Animate the grid
    const grid = document.getElementById('screenshotGrid');
    if (grid) {
      grid.style.transition = 'opacity 0.2s ease';
      grid.style.opacity = '0.4';
      setTimeout(() => { grid.style.opacity = '1'; }, 250);
    }
  });
});

// ── FLOWS TOGGLE ────────────────────────────────────────
document.querySelectorAll('.toggle-btn').forEach(btn => {
